INSERT INTO public.repair_knowledge (topic, content) VALUES
('Договор', 'Работаем по письменному договору. До начала ремонта согласовываем перечень работ, смету и график. Дополнительные работы выполняем только после согласования с клиентом.'),
('Оплата', 'Оплата работ поэтапная. Стоимость и порядок платежей фиксируем в договоре. Материалы оплачиваются отдельно. Точные суммы определяются после осмотра и согласования сметы.'),
('Замер', 'Выезд специалиста для замера и предварительной оценки бесплатный в пределах города, где работает бригада. Дату и время согласовывает менеджер. Возможность выезда за город уточняется отдельно.'),
('Гарантия', 'Гарантия на выполненные ремонтные работы составляет 12 месяцев с даты подписания акта. Условия и исключения фиксируются в договоре. Гарантия производителя на материалы рассматривается отдельно.'),
('Услуги', 'Выполняем косметический и капитальный ремонт квартир, а также отделку новостроек. Возможность демонтажа, вывоза мусора и закупки материалов согласовывается отдельно. Итоговая стоимость определяется по смете.'),
('Сроки', 'Срок ремонта зависит от площади, состояния квартиры и состава работ. Точный срок согласовываем после осмотра и фиксируем в договоре. Менеджер связывается по заявке в течение рабочего дня.')
